10	// windowedChain builds the chain from the time-window specification:
11	// heights 1..4 carry times 105, missing, 100, 110 and transactions
12	// [a,b,a], [a], [a], [a].
13	func windowedChain(t *testing.T) *Index {
14		t.Helper()
15		index := New()
16		blocks := []struct {
17			txs  []string
18			time *int64
19		}{
20			{[]string{"a", "b", "a"}, intptr(105)},
21			{[]string{"a"}, nil},
22			{[]string{"a"}, intptr(100)},
23			{[]string{"a"}, intptr(110)},
24		}
25		for i, entry := range blocks {
26			height := int64(i + 1)
27			parent := "genesis"
28			if height > 1 {
29				parent = fmt.Sprintf("h%d", height-1)
30			}
31			block := Block{
32				Height: height,
33				Hash:   fmt.Sprintf("h%d", height),
34				Parent: parent,
35				Txs:    entry.txs,
36				Time:   entry.time,
37			}
38			if err := index.Append(block); err != nil {
39				t.Fatalf("setup append at %d: %v", height, err)
40			}
41		}
42		return index
43	}
44	
45	func TestQueryTxsTimeWindowSpecExample(t *testing.T) {
46		// Filter a over [100, 110), ascending, two hits per page. Height 2 has
47		// no timestamp and height 4 has time 110 (the excluded end), so only the
48		// two a occurrences at height 1 and the one at height 3 survive.
49		index := windowedChain(t)
